def isNStraightHand(hand, groupSize):
    if len(hand) % groupSize:
        return False
    cnt = {}
    for x in hand:
        cnt[x] = cnt.get(x, 0) + 1
    for x in sorted(cnt):
        c = cnt[x]
        if c == 0:
            continue
        for y in range(x, x + groupSize):
            if cnt.get(y, 0) < c:
                return False
            cnt[y] -= c
    return True
